import{_ as d,o as l,c as r,a4 as i}from"./chunks/framework.BYKJayo6.js";const c=JSON.parse('{"title":"DLC02・競馬場","description":"Anno 117 DLC02「競馬場（The Hippodrome）」の攻略ガイド。戦車競走モニュメント・レースの育成要素・輝きボーナス・無料アップデート2.0を解説。","frontmatter":{"title":"DLC02・競馬場","description":"Anno 117 DLC02「競馬場（The Hippodrome）」の攻略ガイド。戦車競走モニュメント・レースの育成要素・輝きボーナス・無料アップデート2.0を解説。"},"headers":[],"relativePath":"guide/dlc02-hippodrome.md","filePath":"guide/dlc02-hippodrome.md"}'),a={name:"guide/dlc02-hippodrome.md"};function o(e,t,h,n,s,u){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="dlc02・競馬場" tabindex="-1">DLC02・競馬場 <a class="header-anchor" href="#dlc02・競馬場" aria-label="Permalink to &quot;DLC02・競馬場&quot;">​</a></h1><blockquote><p>出典: Anno Union 公式デブログ・Ubisoft News・実機確認。一部の数値は<strong>要検証</strong>。</p></blockquote><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li>ローマの<strong>戦車競走</strong>（チャリオットレース）をテーマにした2つ目のDLC。</li><li>巨大モニュメント「競馬場」を段階建設し、住民向けのレースイベントを開催できる。</li><li>レースには手持ちの<strong>専門家（スペシャリスト）</strong>を騎手として出走させる。走らせるほど騎手の能力が育つ。</li><li>レースで貯まる<strong>輝き</strong>でモニュメントのレベルと島全体へのボーナスが強化される。</li><li>同時配信の無料アップデート2.0で、名誉ある来賓・英雄級スペシャリスト・フォトモード等が全プレイヤーに追加。</li></ul><h2 id="競馬場モニュメント" tabindex="-1">競馬場モニュメント <a class="header-anchor" href="#競馬場モニュメント" aria-label="Permalink to &quot;競馬場モニュメント&quot;">​</a></h2><ul><li><strong>設置面積</strong>: 敷地は約60×28タイルで、円形闘技場（約28×28タイル）の約2倍の広さを要する。</li><li><strong>建設段階</strong>: 基礎 → 外壁・観客席 → 装飾・VIP用貴賓席の順に段階施工する（各フェーズの必要材料は下記「<a href="#競馬場の建築工程">競馬場の建築工程</a>」を参照）。</li><li><strong>需要充足</strong>: パトリキの「驚異」需要カテゴリーに属し、島全体のパトリキの当該需要を満たす。</li><li>観客はエクィテス・パトリキ（貴賓席）から平民（一般席）まで全階層が楽しむ。</li></ul><h2 id="競馬場の建築工程" tabindex="-1">競馬場の建築工程 <a class="header-anchor" href="#競馬場の建築工程" aria-label="Permalink to &quot;競馬場の建築工程&quot;">​</a></h2><ol><li>新スキルツリー「競馬場」が追加される。まず競馬場スキルを解放する。</li><li>競馬場を設置する。円形闘技場と同様、資材搬入のため倉庫を近隣に置くことを推奨。</li><li>建設フェーズを順に進める。フェーズごとに必要材料と必要労働力が異なる。</li></ol><table tabindex="0"><thead><tr><th>フェーズ</th><th>必要材料</th><th>必要労働力</th></tr></thead><tbody><tr><td>1</td><td>設置のみ</td><td>—</td></tr><tr><td>2</td><td>木材 180／縄 150／瓦 150／布 120</td><td>リベルトゥス 600人</td></tr><tr><td>3</td><td>木材 160／瓦 160／コンクリート 200／鉄 120／<strong>花崗岩</strong> 160</td><td>プレブス 500人</td></tr><tr><td>4</td><td>瓦 300／コンクリート 250／鉄 200／<strong>花崗岩</strong> 200／大理石 300／モザイク 300</td><td>エクィテス 400人</td></tr><tr><td>5</td><td>コンクリート 180／大理石 240／モザイク 120／<strong>青銅</strong> 240／クッション 300／装飾木材 300</td><td>パトリキ 300人</td></tr></tbody></table><ul><li>花崗岩・青銅などのアルビオン（ケルト）産の製品が必要になるため、事前に調達しておくとよい。</li></ul><h2 id="チャリオットレース" tabindex="-1">チャリオットレース <a class="header-anchor" href="#チャリオットレース" aria-label="Permalink to &quot;チャリオットレース&quot;">​</a></h2><ul><li>出走させる騎手（スペシャリスト）は次の4能力を持つ。 <ul><li>速度</li><li>スタミナ</li><li>ダッシュ</li><li>信頼性</li></ul></li><li>レース中は<strong>ダッシュ</strong>を発動して一時的に加速できる。</li><li>レース種別は3種。輝きレベルを上げると上位種別が解放される。</li></ul><table tabindex="0"><thead><tr><th>種別</th><th>出走数</th><th>解放条件</th></tr></thead><tbody><tr><td>アマチュア</td><td>4</td><td>初期から</td></tr><tr><td>クラシック・クアドリガ</td><td>6</td><td>輝きレベルの上昇</td></tr><tr><td>インペリアル</td><td>8</td><td>輝きレベルの上昇</td></tr></tbody></table><ul><li>大きなレースほど得られる輝きは多いが、必要な準備物資・対戦相手の強さも増す。</li><li><strong>騎手の育成</strong>: 出走を重ねると能力が伸びる。ただし騎手ごとに上限値と得意分野が異なる。</li></ul><h3 id="レースの流れ" tabindex="-1">レースの流れ <a class="header-anchor" href="#レースの流れ" aria-label="Permalink to &quot;レースの流れ&quot;">​</a></h3><ul><li>レースは<strong>準備フェーズ → 試合フェーズ → クールダウン時間</strong>の順で進行する。</li><li>試合フェーズが終了した時点で試走回数がリセットされる（最大回数は1回。スキル「たゆまぬ訓練」の解放で+2され、最大3回になる）。</li><li>試走を行うと、ステータス上限に達していない場合はステータスが向上する。</li><li>ダッシュゲージが一定量まで上昇した時点でボタンを押すと、ダッシュが可能になる。</li></ul><h2 id="輝きボーナス" tabindex="-1">輝きボーナス <a class="header-anchor" href="#輝きボーナス" aria-label="Permalink to &quot;輝きボーナス&quot;">​</a></h2><ul><li>獲得量はレース種別・供給した準備物資・着順で決まる。</li><li>貯めた輝きでモニュメントのレベルと新レース種別が解放される。</li><li>レベルが上がると島全体に次の効果が生じる: <ul><li>周辺の生産力が上昇する。</li><li>騎兵の攻撃・防御が強化される（+1 攻撃 / +2 防御）。</li><li>ランクVIIで、上流階級（エクィテス／パトリキ）の住居に<strong>馬</strong>の需要が追加される。「家庭」の需要で、満たすと人口 +2・幸福度 +1・名声 +3（実機確認済み）。</li><li>ランクXで、馬ブリーダーが追加の生産物として<strong>戦車</strong>を供給し、馬ブリーダーを中心にした円形の範囲内の生産施設の生産性が20%上がる（実機確認済み。範囲は馬ブリーダーを選ぶと表示される外側の大きな円）。</li></ul></li></ul><p>ランクごとの必要な輝きや効果の一覧は、<a href="/wiki/splendor.html">モニュメントの輝き</a>にまとめています。</p><h2 id="新規リサーチ・アイテム" tabindex="-1">新規リサーチ・アイテム <a class="header-anchor" href="#新規リサーチ・アイテム" aria-label="Permalink to &quot;新規リサーチ・アイテム&quot;">​</a></h2><ul><li>騎手育成に関わる新しいリサーチ技術が追加。</li><li>関連アイテムはクエスト報酬・ウァレリアとの交易・反復リサーチで入手できる。</li></ul><h2 id="無料アップデート2-0-dlc不要" tabindex="-1">無料アップデート2.0（DLC不要） <a class="header-anchor" href="#無料アップデート2-0-dlc不要" aria-label="Permalink to &quot;無料アップデート2.0（DLC不要）&quot;">​</a></h2><ul><li><strong>名誉ある来賓</strong>: 各地から来賓が訪れ、新スペシャリストなどをもたらす。出現率は<strong>名声（Prestige）</strong>と輝きのレベルに依存。確率の中身は<a href="#来訪する専門家の確率">来訪する専門家の確率</a>を参照。</li><li><strong>英雄級（Heroic）スペシャリスト</strong>: 新レア度。極めて希少で名声コストが高く、セーブデータごとに各1体のみ所持可。効果は強力。 <ul><li>（例）「パルディウス」— チーズによる人口+2・健康+1、羊牧場のチーズ産出+1t/12サイクル、羊牧場の必要労働力を軽減。</li></ul></li><li><strong>フォトモード</strong>: フリーカメラ・時間帯選択・レンズ効果。</li><li><strong>メモ機能</strong>: ゲーム内メモ。</li><li>円形闘技場の10段階バフシステム。輝きレベルIVでリベルトゥスの需要に<strong>パン</strong>が追加される（気づかないうちにパン需要が急増するため要注意）。</li><li>住民の反復クエスト。</li><li>パンの消費量+50%。供給時の人口ボーナスが+2→+3に増加し、小麦粉の生産時間が30秒/tから20秒/tに短縮。</li><li>火災・疫病の建物への影響を強化。</li></ul><p>2026年8月20日追加。</p><h2 id="来訪する専門家の確率" tabindex="-1">来訪する専門家の確率 <a class="header-anchor" href="#来訪する専門家の確率" aria-label="Permalink to &quot;来訪する専門家の確率&quot;">​</a></h2><p>専門家が来訪するときのレア度は、都市の<strong>名声</strong>とモニュメントの<strong>輝き</strong>で決まります。到着までの時間が出る画面に、レア度ごとの確率が表示されます。</p><ul><li>都市の名声が高いほど、レア度の高い専門家が訪れやすくなります。名声で来訪する専門家の最高レア度は<strong>レジェンダリー</strong>です。</li><li><strong>ヒロイック</strong>の専門家は、モニュメントの輝きでのみ引き寄せられます。輝きの階層が1段階上がるごとに、ヒロイックの出現確率が<strong>2%</strong>増えます。</li><li>名声が<strong>5,000未満</strong>の都市には、来訪者が来ません。到着までの時間も進まず、画面に「名声が不足」と出ます（実機で確認）。</li></ul><p>画面に出ていた例です（実機で確認）。</p><table><thead><tr><th>条件</th><th>レア</th><th>エピック</th><th>レジェンダリー</th><th>ヒロイック</th></tr></thead><tbody><tr><td>名声 47,270、競馬場ランクIV、円形闘技場ランクIX</td><td>7%</td><td>50%</td><td>17%</td><td>26%</td></tr><tr><td>名声 46,632、競馬場ランクIV、円形闘技場ランクIX</td><td>7%</td><td>51%</td><td>16%</td><td>26%</td></tr><tr><td>名声 130.7K、競馬場ランクVIII、円形闘技場ランクIX</td><td>3%</td><td>27%</td><td>36%</td><td>34%</td></tr></tbody></table><ul><li>3つの例とも、ヒロイックの確率は 2% × （競馬場のランク + 円形闘技場のランク）と一致します（34% = 2% × (8 + 9)、26% = 2% × (4 + 9)）。ゲーム内データにも「輝きの階層ごとに2%」という定義があり、複数のモニュメントの階層が合算されるとみられます。</li><li>名声が高い例のほうが、レジェンダリーの確率が高く出ています（名声 46,632 で16%、130.7K で36%）。</li></ul><h3 id="名声とレア度の確率の式" tabindex="-1">名声とレア度の確率の式 <a class="header-anchor" href="#名声とレア度の確率の式" aria-label="Permalink to &quot;名声とレア度の確率の式&quot;">​</a></h3><p>ゲーム内データには、レア・エピック・レジェンダリーの「重み」が名声に応じてS字に変わる式が定義されています（実機の例と照らして確認済み）。</p><table><thead><tr><th>レア度</th><th>名声が低いときの重み</th><th>名声が高いときの重み</th><th>切り替わりの目安（名声）</th></tr></thead><tbody><tr><td>レア</td><td>90</td><td>10</td><td>12,500</td></tr><tr><td>エピック</td><td>20</td><td>80</td><td>15,500</td></tr><tr><td>レジェンダリー</td><td>0（指定なし）</td><td>120</td><td>80,000</td></tr></tbody></table><p>各レア度の確率は、「その重み ÷ 3つの重みの合計 × （100% − ヒロイックの確率）」です。名声を決めたときの計算値は、ヒロイックが0%（モニュメントの輝きなし）の場合で次のとおりです。ヒロイックが出る場合は、残りの確率をこの比率で分けます。</p><table><thead><tr><th>名声</th><th>レア</th><th>エピック</th><th>レジェンダリー</th></tr></thead><tbody><tr><td>5,000</td><td>64%</td><td>30%</td><td>6%</td></tr><tr><td>10,000</td><td>55%</td><td>38%</td><td>7%</td></tr><tr><td>20,000</td><td>34%</td><td>57%</td><td>9%</td></tr><tr><td>30,000</td><td>20%</td><td>67%</td><td>13%</td></tr><tr><td>50,000</td><td>10%</td><td>67%</td><td>23%</td></tr><tr><td>80,000</td><td>7%</td><td>53%</td><td>40%</td></tr><tr><td>100,000</td><td>6%</td><td>46%</td><td>48%</td></tr><tr><td>150,000</td><td>5%</td><td>39%</td><td>56%</td></tr><tr><td>210,000</td><td>5%</td><td>38%</td><td>57%</td></tr></tbody></table><p>画面に出る数値は、この式の計算値と1ポイントほどずれることがあります（実機の例で確認。原因は未確認です）。</p><h2 id="関連データ" tabindex="-1">関連データ <a class="header-anchor" href="#関連データ" aria-label="Permalink to &quot;関連データ&quot;">​</a></h2><ul><li><a href="/wiki/techs-dlc02.html">スキルツリー・競馬場</a> — DLC02で追加されるスキル</li><li><a href="/wiki/splendor.html">モニュメントの輝き</a> — 競馬場・円形闘技場の「輝き」ランクと専門家のレース適性</li></ul>',38)])])}const b=d(a,[["render",o]]);export{c as __pageData,b as default};
